"""Paper 2 Business Laws — extra practice MCQs, Chapters 1 and 2 (original questions; sections cited, no text copied)."""
from ca_bank import Q

AR = ['A and R are both true; R explains A', 'A and R are both true; R does not explain A',
      'A is true; R is false', 'A is false; R is true']
def ar(k):
    """assertion-reason options with the correct one first (k = index in AR)"""
    return [AR[k]] + [x for i, x in enumerate(AR) if i != k]

BANK = {}

